 const [year,setYear]=useState('2027'),[quarter,setQuarter]=useState('Q1'),[month,setMonth]=useState('All'),[search,setSearch]=useState(''),[goal,setGoal]=useState('All'),[status,setStatus]=useState('All');
 const initialized=useRef(false);
 const [levelScope,setLevelScope]=useState<{id:string;title:string;unit:string}|null>(null),[riskEditing,setRiskEditing]=useState<{flag:RiskFlag;metric:Metric;review:boolean}|null>(null);
